import { isPositiveSafeInteger, validateNodeId } from "./validation.js";
import { INVALID_ARGUMENT } from "../../errors/index.js";
/** Create a mapped workflow step. */
export function map(id, options) {
    validateNodeId(id);
    if (!options.items) {
        throw INVALID_ARGUMENT.create({ detail: `Map node "${id}" must have 'items' configured` });
    }
    if (!options.processor) {
        throw INVALID_ARGUMENT.create({
            detail: `Map node "${id}" must have a 'processor' configured`,
        });
    }
    if (options.concurrency !== undefined && !isPositiveSafeInteger(options.concurrency)) {
        throw INVALID_ARGUMENT.create({
            detail: `Map node "${id}" concurrency must be a positive safe integer`,
        });
    }
    const config = {
        type: "map",
        description: options.description,
        items: options.items,
        processor: options.processor,
        concurrency: options.concurrency,
        checkpoint: options.checkpoint ?? true,
        retry: options.retry,
        timeout: options.timeout,
        skip: options.skip,
    };
    return { id, config };
}
